with unpacked as (select id, service, log_ts, latency_ms, payload_json, get_json_object(payload_json, '$.user.id') as user_id, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec from app_logs) select date_trunc('hour', log_ts) as hour_window, service, date_trunc('day', log_ts) as activity_day, count(*) filter (where service = 'billing') as billing_rows, sum(case when service = 'auth' then latency_ms else 0 end) as auth_latency_ms, round(sum(duration_sec) / nullif(count(case when service = 'auth' then 1 end), 0), 2) as duration_sec_per_auth, approx_percentile(duration_sec, array(0.25, 0.5, 0.75)) as duration_sec_quartiles, sum(case when service = 'billing' then duration_sec else 0 end) as billing_duration_sec from unpacked group by hour_window, service, activity_day
